mapper.update:
update user_error_types
set status = 'ARCHIVED',
    updated_at = #{updatedAt}
where id = #{id}
  and user_id = #{userId}
  and status = 'ACTIVE'

mapper.select:
select count(1)
from user_error_types
where user_id = #{userId}
  and status = #{status}
  and learning_mode = #{learningMode}
